arguments.command:
cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill
while read -r line; do
  ct=${line%%|*}; rest=${line#*|}; sha=${rest%%|*}; rest=${rest#*|}; b=${rest%%|*}
  echo "=== [$b] $(date -u -d @$ct +%H:%M:%S) ${sha:0:8}";
  git show -s --format=%B $sha | sed -n '/^$/,$p' | tail -n +2;
  echo
done < <(tail -24 /tmp/allmsgs.txt)
